  for (const k of keptCheckins()) if (!findCheckin(k.day, k.slot) && (k.local || !k.by || k.by === state.name)) list.push({ at: k.at, reopen: 'checkin:' + k.slot + ':' + k.day, title: checkinTitle(k.slot) });
  list.sort((a, b) => b.at - a.at);
