  const o = h('div', { class: 'scheck' }, h('div', { class: 'scheck-backdrop', onclick: () => done(false) }), panel);
  o.addEventListener('keydown', (ev) => { if (ev.key === 'Escape') { ev.stopPropagation(); done(false); } });
