  const t = dose.match(/^(\d+(?:\.\d+)?|\u00bd|half an?|half|one|two|three|four)\s+(tablet|capsule|sachet|puff|drop)s?(?:\s*\(([^()]+)\)|\s*,\s*(each\b.+))?$/i);
